function smallestSubarrays(nums) {
  const n = nums.length;
  const nearest = new Array(30).fill(-1);
  const answer = new Array(n);

  for (let i = n - 1; i >= 0; i--) {
    for (let bit = 0; bit < 30; bit++) {
      if ((nums[i] >> bit) & 1) {
        nearest[bit] = i;
      }
    }
    let end = i;
    for (let bit = 0; bit < 30; bit++) {
      end = Math.max(end, nearest[bit]);
    }
    answer[i] = end - i + 1;
  }
  return answer;
}

