function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const style = Math.floor(rand() * 3);
  const nums = Array.from({ length: n }, () => {
    if (style === 0) return Math.floor(rand() * (size === 'large' ? 1000000001 : 16));
    if (style === 1) return rand() < 0.7 ? 0 : 2 ** Math.floor(rand() * (size === 'large' ? 30 : 4));
    return rand() < 0.4 ? 0 : Math.floor(rand() * 8);
  });
  return [nums];
}
